INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Schon beim Öffnen der Sendung war ich begeistert über die liebevolle und wertige Verpackung und Aufmachung. Über den Vorgang, dass man selber die hochwertigen Öle unter die Basiscreme rührt, bekommt man einen guten Bezug zur Creme und den Inhaltsstoffen. Das hat mir persönlich richtig gut gefallen.  So war ich gespannt, ob sich dieser sehr positive Ersteindruck auch in der Pflege fortsetzt. JA, eine feine Cremekonsistenz, die gut einzieht und nicht auf der Hautoberfläche klebt. Ich habe ein tolles Hautgefühl. Ich nutze die Creme seit ca. 3 Wochen morgens und abends nach der Reinigung. Meine Haut hat sich bereits erholt und fühlt sich weich und entspannt an. Ich empfehle von Herzen diese Creme und werde definitiv mir noch weitere Produkte von herbsom zulegen.', 'Katy', 'katy.schoeberl@web.de', 'approved', '2025-01-02 23:00:00', 0, 0);
