INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich es 4 Tage benutz, und merke schon jetzt ein großes Besserung. Mein haut ist so weiß und es sieht immer gepflegt aus. Ich habe nur eine kleine Probleme gemerkt und es war mein Haut wird bisschen mehr fertig als sonst. Ich weiß es nicht voran es liegt aber ich mag die Creme sehr gerne. Werde weiter von ihnen bestellen.', 'Mahdiyah Abozaid', 'mahdiyah.abozaid@gmail.com', 'approved', '2022-11-27 23:00:00', 0, 0);